      "commitCount": 25,
      "prCount": 5,
      "issueCount": 3,
      "consistencyScore": 0.85,
      "lastUpdated": "2024-01-15T16:30:00Z"
    }
  }
}
```

**Expected Response (Success - Updated Metrics):**
